const input = $input.first().json || {};
const msg = String(input.user_message || '').toLowerCase();
const intent = input.intent || 'POSTVENTA';

let caseType = input.case_type || 'postventa_general';
if (/devoluci[oó]n|reembolso|dinero|reintegr/i.test(msg)) caseType = 'refund_request';
else if (/no.*lleg|qr|entrada|mail|correo/i.test(msg)) caseType = 'ticket_not_received';
else if (/cancelad/i.test(msg)) caseType = 'event_cancelled';
else if (/suspendid/i.test(msg)) caseType = 'event_suspended';
else if (/llegad[ao] tarde|ingreso|acceso/i.test(msg)) caseType = 'access_issue';

const policies = {
  refund_request: {
    response: 'Las devoluciones requieren revisión humana. El agente puede orientar sobre la política, pero no debe aprobar reembolsos ni solicitar datos bancarios en la primera respuesta automática.',
    requires_human: true,
    next_action: 'escalar_a_boleteria'
  },
  ticket_not_received: {
    response: 'Si la entrada no llegó, se recomienda revisar Spam, Promociones o Correo no deseado. Si el problema continúa, el equipo de boletería debe revisar el pedido asociado antes de confirmar reenvío.',
    requires_human: true,
    next_action: 'revisar_pedido_en_boleteria'
  },
  event_cancelled: {
    response: 'Ante una función cancelada, la organización puede ofrecer reembolso, custodia de reserva o reprogramación. La opción aplicable debe ser confirmada por el equipo humano.',
    requires_human: true,
    next_action: 'confirmar_alternativa_oficial'
  },
  event_suspended: {
    response: 'Ante una suspensión, la alternativa depende de si la actividad inició o no. Puede corresponder reembolso total, parcial, cupón, custodia o reprogramación, siempre sujeto a revisión humana.',
    requires_human: true,
    next_action: 'evaluar_causa_suspension'
  },
  access_issue: {
    response: 'El ingreso depende de la política de sala, horario de función y condiciones del evento. Si hubo llegada tarde, QR inválido o accesibilidad, corresponde revisión humana.',
    requires_human: true,
    next_action: 'derivar_a_sala_o_boleteria'
  },
  postventa_general: {
    response: 'La consulta corresponde a postventa. Se puede orientar con datos generales, pero cualquier cambio, devolución, reenvío o validación de acceso requiere revisión del equipo.',
    requires_human: false,
    next_action: 'orientar_y_solicitar_datos_minimos'
  }
};

const selected = policies[caseType] || policies.postventa_general;

return [{
  json: {
    status: 'success',
    worker: 'worker_postventa_reclamos_ticketing',
    intent,
    case_type: caseType,
    request_id: input.request_id || null,
    session_id: input.session_id || null,
    response: selected.response,
    requires_human: selected.requires_human,
    next_action: selected.next_action,
    governance: {
      no_refund_approval: true,
      no_ticket_resend_confirmation: true,
      no_sensitive_data_request: true,
      fallback_available: true
    },
    error: null
  }
}];
